bash -lc /bin/bash -lc "node <<'JS'
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const html = fs.readFileSync('dist/index.html', 'utf8');
const scripts = [...html.matchAll(/<script(?:\\s["'^>]*)?>(['"\\s\\S]*?)<\\/script>/g)].map(m => m[1]);
assert.equal(scripts.length, 2);
scripts.forEach((s, i) => new vm.Script(s, {filename: "'`script-${i}.js`}));
const ids = [...html.matchAll(/'"\\bid=\"(["'^"]+)"/g)].map(m => m[1]);
assert.equal(new Set(ids).size, ids.length, '"'No duplicate HTML IDs');
for (const m of scripts[1].matchAll(/\\"'$'"\\('(["'^'"']+)'\\)/g)) assert.ok(ids.includes(m[1]), "'`Missing element: ${m[1]}`);
assert.equal([...html.matchAll(/'"\\b(?:src|href)=\"(?"'!#)([''^"]+)"/g)].length, 0, '"'Self-contained file');
const manifest = JSON.parse(fs.readFileSync('.openai/hosting.json', 'utf8'));
assert.equal(manifest.static.directory, 'dist');
assert.ok(manifest.project_id);
const context = vm.createContext({});
vm.runInContext(scripts[0] + '\\nthis.Game = SnakeGame;', context);
const Game = context.Game;
let count = 0;
const check = (name, fn) => { fn(); count++; console.log('PASS ' + name); };
check('Start, movement, score and unoccupied food spawn', () => {
  const g = new Game(24, () => 0);
  g.phase = 'playing';
  for (let i = 0; i < 7; i++) g.step();
  assert.equal(g.score, 10); assert.equal(g.snake.length, 6);
  assert.ok("'!g.snake.some(p => p.x === g.food.x && p.y === g.food.y));
});
check('"'Wall collision ends the round', () => {
  const g = new Game(); g.phase = 'playing';
  g.snake = [{x:23,y:12},{x:22,y:12}];
  assert.equal(g.step(), 'over'); assert.equal(g.phase, 'over');
});
check('Body collision ends the round', () => {
  const g = new Game(); g.phase = 'playing';
  g.snake = [{x:2,y:2},{x:2,y:3},{x:3,y:3},{x:3,y:2},{x:4,y:2}];
  assert.equal(g.step(), 'over');
});
check('Moving into a vacating tail is allowed', () => {
  const g = new Game(); g.phase = 'playing';
  g.snake = [{x:2,y:2},{x:2,y:3},{x:3,y:3},{x:3,y:2}];
  assert.equal(g.step(), 'move'); assert.equal(g.phase, 'playing');
});
check('Reverse turns blocked; rapid valid turns buffered', () => {
  const g = new Game(); g.phase = 'playing';
  g.turn({x:-1,y:0}); assert.equal(g.queue.length, 0);
  g.turn({x:0,y:-1}); g.turn({x:-1,y:0});
  g.step(); assert.equal(g.snake[0].x, 8); assert.equal(g.snake[0].y, 11);
  g.step(); assert.equal(g.snake[0].x, 7); assert.equal(g.snake[0].y, 11);
});
check('Pause freezes the board; restart resets state', () => {
  const g = new Game(); g.phase = 'paused';
  const state = JSON.stringify(g.snake); assert.equal(g.step(), 'idle');
  assert.equal(JSON.stringify(g.snake), state);
  g.score = 80; g.queue.push({x:0,y:-1}); g.reset();
  assert.equal(g.score, 0); assert.equal(g.queue.length, 0); assert.equal(g.phase, 'ready');
});
check('Final food fills the board and wins', () => {
  const g = new Game(2); g.phase = 'playing';
  g.snake = [{x:0,y:0},{x:0,y:1},{x:1,y:1}];
  g.direction = {x:1,y:0}; g.food = {x:1,y:0};
  assert.equal(g.step(), 'won'); assert.equal(g.food, null); assert.equal(g.snake.length, 4);
});
console.log("'`${count} gameplay checks passed. HTML IDs, entrypoint, self-contained assets and both scripts validated.`);
JS'
